const DAILY_LIMIT   = 3000; // change to 30000 for production
const CURRENT_MONTH = new Date().toISOString().slice(0, 7);

const sd = $getWorkflowStaticData('global');
sd.run_started_at = new Date().toISOString();
sd.current_month  = CURRENT_MONTH;
sd.daily_limit    = DAILY_LIMIT;
sd.processed      = 0;

return [{ json: { current_month: CURRENT_MONTH, daily_limit: DAILY_LIMIT } }];

const url = $json.lemlistprofileurl || '';
const match = url.match(/linkedin\.com\/company\/([^/?#]+)/i);

let vanity_name = null;
if (match) {
  try {
    vanity_name = decodeURIComponent(match[1]).trim();
  } catch (e) {
    vanity_name = match[1].trim();
  }
}

return {
  json: {
    ...$json,
    vanity_name: vanity_name,
    linkedin_last_checked: new Date().toISOString()
  }
};

const response = $json;
const extracted = $node['Extract Vanity Name'].json;

let status = 'success';
let linkedinId = null;
let linkedinVanityName = null;
let linkedinCompanyPage = null;
let adsLibraryUrl = null;
let errorMessage = null;

if (response.error || (response.statusCode && response.statusCode >= 400)) {
  status = `linkedin_error_${response.statusCode || 'unknown'}`;
  errorMessage = response.message || response.error || JSON.stringify(response);
} else {
  const elements = response.elements || [];
  if (!elements.length) {
    status = 'not_found';
    errorMessage = 'No LinkedIn organization found for vanity name';
  } else {
    const org = elements[0];
    linkedinId = org.id || null;
    linkedinVanityName = org.vanityName || extracted.vanity_name;
    linkedinCompanyPage = linkedinVanityName
      ? `https://www.linkedin.com/company/${linkedinVanityName}/`
      : extracted.lemlistprofileurl;
    if (linkedinId) {
      adsLibraryUrl = `https://www.linkedin.com/ad-library/search?companyIds=${linkedinId}`;
    } else {
      status = 'missing_id';
      errorMessage = 'LinkedIn response did not contain organization ID';
    }
  }
}

const sd = $getWorkflowStaticData('global');
const now = new Date().toISOString();

const properties = {
  linkedin_ads_library_sync_status: status,
  linkedin_ads_library_sync_month:  sd.current_month || now.slice(0, 7),
  linkedin_ads_library_last_checked: now
};
if (linkedinId)   properties.linkedin_company_id      = String(linkedinId);
if (adsLibraryUrl) properties.linkedin_ads_library_url = adsLibraryUrl;

return {
  json: {
    ...extracted,
    retrieved_linkedin_id:      linkedinId,
    retrieved_vanity_name:      linkedinVanityName,
    normalized_lemlistprofileurl: linkedinCompanyPage,
    new_linkedin_ads_library_url: adsLibraryUrl,
    linkedin_sync_status:       status,
    linkedin_sync_error:        errorMessage,
    linkedin_last_checked:      now,
    linkedin_sync_month:        properties.linkedin_ads_library_sync_month,
    update_payload:              { properties }
  }
};

const sd = $getWorkflowStaticData('global');
const now = new Date().toISOString();
const input = $json;

const properties = {
  linkedin_ads_library_sync_status: 'no_vanity',
  linkedin_ads_library_sync_month:  sd.current_month || now.slice(0, 7),
  linkedin_ads_library_last_checked: now
};

return {
  json: {
    ...input,
    linkedin_sync_status: 'no_vanity',
    linkedin_last_checked: now,
    update_payload: { properties }
  }
};

const TOKEN = '[YOUR_HUBSPOT_TOKEN]';
const sd = $getWorkflowStaticData('global');
const DAILY_LIMIT    = sd.daily_limit || 3000;
const CURRENT_MONTH = sd.current_month;
const BATCH_SIZE    = 100;

const allCompanies = [];
let cursor = '';

while (allCompanies.length < DAILY_LIMIT) {
  const body = {
    limit: BATCH_SIZE,
    sorts: [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }],
    properties: [
      'lemlistprofileurl',
      'linkedin_company_id',
      'linkedin_ads_library_url',
      'linkedin_ads_library_last_checked',
      'linkedin_ads_library_sync_status',
      'linkedin_ads_library_sync_month'
    ],
    filterGroups: [
      {
        filters: [
          { propertyName: 'lemlistprofileurl', operator: 'HAS_PROPERTY' },
          { propertyName: 'linkedin_ads_library_sync_month', operator: 'NOT_HAS_PROPERTY' }
        ]
      },
      {
        filters: [
          { propertyName: 'lemlistprofileurl', operator: 'HAS_PROPERTY' },
          { propertyName: 'linkedin_ads_library_sync_month', operator: 'NEQ', value: CURRENT_MONTH }
        ]
      }
    ]
  };

  if (cursor) body.after = cursor;

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.hubapi.com/crm/v3/objects/companies/search',
    headers: {
      'Authorization': `Bearer ${TOKEN}`,
      'Content-Type': 'application/json'
    },
    body: body,
    json: true
  });

  const results    = response.results || [];
  const nextCursor = response.paging?.next?.after || '';

  const remaining = DAILY_LIMIT - allCompanies.length;
  const toAdd     = results.slice(0, remaining);

  for (const company of toAdd) {
    const p = company.properties || {};
    allCompanies.push({
      json: {
        hubspot_company_id:           company.id,
        lemlistprofileurl:         p.lemlistprofileurl || null,
        existing_linkedin_company_id: p.linkedin_company_id || null,
        existing_ads_library_url:      p.linkedin_ads_library_url || null,
        current_month:                CURRENT_MONTH
      }
    });
  }

  if (!nextCursor || results.length === 0) break;
  cursor = nextCursor;
}

return allCompanies;
